WITH filtered_customers AS (SELECT *, SUBSTRING(name, 1, 2) AS name_prefix FROM customers WHERE age >= 53 AND segment = 'Consumer'), signup_month_summary AS (SELECT DATE_FORMAT(signup_date, 'yyyy-MM') AS signup_month, MAX(age) AS max_age, COUNT(*) AS total_count FROM filtered_customers GROUP BY DATE_FORMAT(signup_date, 'yyyy-MM')) SELECT * FROM signup_month_summary ORDER BY signup_month DESC LIMIT 3
